        seq INTEGER PRIMARY KEY AUTOINCREMENT,
        event_id TEXT NOT NULL UNIQUE,
        authority_id TEXT NOT NULL REFERENCES authority(authority_id) ON DELETE RESTRICT,
        epoch INTEGER NOT NULL CHECK(epoch>0),
